// The time slice a screen is showing: All time, one month, one year, or a
// custom range. Ported 1:1 from mobile/lib/format.js (inPeriod, periodLabel,
// shiftPeriod, periodIsFuture, monthLabel) and golden locked against output
// generated by executing that file.
//
// Nothing here does arithmetic on money, but it decides WHICH money a screen
// adds up, which is the same thing one step earlier. A period that quietly
// excludes an entry makes every total on the screen wrong while every total
// still looks right.
//
// The comparisons are all LEXICAL on 'YYYY-MM-DD' text, never on parsed dates,
// exactly as the RN original is. That is deliberate there and kept here: text
// comparison has no timezone, so an entry logged on the 1st cannot fall into
// the previous month because the device is east of UTC.

const _monthNames = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

/// The four shapes a period can take. Stored as text rather than an enum
/// because the RN original compares strings and falls THROUGH to the month
/// rule for anything it does not recognise, and a Dart enum cannot hold a
/// value that is not one of the four.
abstract final class PeriodMode {
  static const all = 'all';
  static const month = 'month';
  static const year = 'year';
  static const custom = 'custom';
}

class Period {
  final String mode;

  /// 'YYYY-MM' for a month period.
  final String? ym;

  /// 'YYYY' for a year period.
  final String? y;

  /// 'YYYY-MM-DD' bounds for a custom range. Either may be absent, which
  /// leaves that end open.
  final String? from, to;

  const Period({required this.mode, this.ym, this.y, this.from, this.to});

  const Period.all() : this(mode: PeriodMode.all);
  const Period.month(String ym) : this(mode: PeriodMode.month, ym: ym);
  const Period.year(String y) : this(mode: PeriodMode.year, y: y);
  const Period.custom({String? from, String? to})
    : this(mode: PeriodMode.custom, from: from, to: to);

  /// The month containing [d], the History screen's opening slice.
  factory Period.monthOf(DateTime d) => Period.month(
    '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}',
  );

  // No copyWith. The obvious one, `from: from ?? this.from`, cannot CLEAR a
  // bound: passing null silently keeps the old value. It had no callers, and
  // the selector already hand builds a Period to dodge it. A dead helper whose
  // null argument means "ignore me" is exactly the shape that has bitten this
  // codebase before, so it is gone rather than documented.

  @override
  bool operator ==(Object other) =>
      other is Period &&
      other.mode == mode &&
      other.ym == ym &&
      other.y == y &&
      other.from == from &&
      other.to == to;

  @override
  int get hashCode => Object.hash(mode, ym, y, from, to);
}

final _fullDate = RegExp(r'^\d{4}-\d{2}-\d{2}$');

/// JS truthiness, which is what the original's `dateStr ? ... : ''` relies on.
/// An entry with no date, an empty date, or a zero is NOT in any period except
/// All time, and that is deliberate in the RN comment: every real entry is
/// dated at creation, so a dateless one only comes from a hand edited backup,
/// and counting it would put it in every month at once.
bool _truthy(dynamic v) =>
    v != null && v != false && v != '' && !(v is num && (v == 0 || v.isNaN));

/// Whether an entry dated [dateStr] falls inside [period].
bool inPeriod(dynamic dateStr, Period? period) {
  if (period == null || period.mode == PeriodMode.all) return true;
  final s = _truthy(dateStr) ? dateStr.toString() : '';
  final d = s.length > 10 ? s.substring(0, 10) : s;
  if (d.isEmpty) return false;

  if (period.mode == PeriodMode.year) {
    return d.length >= 4 && d.substring(0, 4) == period.y;
  }
  if (period.mode == PeriodMode.custom) {
    // A bound only applies once it is a COMPLETE YYYY-MM-DD. A half typed
    // '2026' or an unpadded '2026-6-1' counts as not set rather than silently
    // mis-filtering, because the comparison is lexical and '2026-6-1' sorts
    // after every date in 2026.
    final from = _fullDate.hasMatch(period.from ?? '') ? period.from! : '';
    final to = _fullDate.hasMatch(period.to ?? '') ? period.to! : '';
    if (from.isNotEmpty && d.compareTo(from) < 0) return false;
    if (to.isNotEmpty && d.compareTo(to) > 0) return false;
    return true;
  }
  // month, and anything unrecognised, which the original also lands here.
  return (d.length >= 7 ? d.substring(0, 7) : d) == period.ym;
}

/// 'July 2026' for the month containing [ref].
String monthLabel(DateTime ref) => '${_monthNames[ref.month - 1]} ${ref.year}';

/// The human title for a period: 'July 2026', '2026', a range, or 'All time'.
///
/// Returns '' for a month period whose ym is missing or unparseable, and for a
/// year period with no year. Both are RN's own answers, and neither is
/// reachable from the selector: it only ever builds complete periods. They are
/// locked so a future refactor cannot quietly start rendering the word 'null'
/// on the screen instead.
String periodLabel(Period? period) {
  if (period == null || period.mode == PeriodMode.all) return 'All time';
  if (period.mode == PeriodMode.year) return period.y ?? '';
  if (period.mode == PeriodMode.custom) {
    final from = period.from ?? '', to = period.to ?? '';
    if (from.isNotEmpty && to.isNotEmpty) return '$from to $to';
    if (from.isNotEmpty) return 'From $from';
    if (to.isNotEmpty) return 'Until $to';
    return 'All dates';
  }
  final parts = (period.ym ?? '').split('-');
  final y = parts.isNotEmpty ? int.tryParse(parts[0]) : null;
  final m = parts.length > 1 ? int.tryParse(parts[1]) : null;
  if (y == null || y == 0 || m == null || m == 0) return '';
  // DateTime normalises the same way JS Date does, so a month of 13 rolls
  // into the next January rather than throwing. Locked, because that is what
  // the live app prints.
  return monthLabel(DateTime(y, m, 1));
}

/// Steps a month or year period by [delta]. A custom range has explicit dates
/// and comes back unchanged, as does anything with an unrecognised mode.
Period? shiftPeriod(Period? period, int delta) {
  if (period == null) return null;
  if (period.mode == PeriodMode.year) {
    final n = int.tryParse(period.y ?? '');
    // RN produces the literal string 'NaN' here rather than refusing. Kept,
    // because the alternative is inventing a year the live app never shows.
    // Unreachable from the selector, which never builds a period without one.
    return Period.year(n == null ? 'NaN' : '${n + delta}');
  }
  if (period.mode == PeriodMode.month) {
    final parts = (period.ym ?? '').split('-');
    final y = parts.isNotEmpty ? int.tryParse(parts[0]) : null;
    final m = parts.length > 1 ? int.tryParse(parts[1]) : null;
    if (y == null || m == null) return const Period.month('NaN-NaN');
    final d = DateTime(y, m + delta, 1);
    return Period.month(
      '${d.year.toString().padLeft(4, '0')}-'
      '${d.month.toString().padLeft(2, '0')}',
    );
  }
  return period;
}

/// True when the whole period is past [ref], so a screen can stop the user
/// stepping forward into a month or year that cannot contain anything.
bool periodIsFuture(Period? period, DateTime ref) {
  if (period == null) return false;
  final now =
      '${ref.year.toString().padLeft(4, '0')}-'
      '${ref.month.toString().padLeft(2, '0')}-'
      '${ref.day.toString().padLeft(2, '0')}';
  if (period.mode == PeriodMode.year) {
    return (period.y ?? '').compareTo(now.substring(0, 4)) > 0 &&
        period.y != null;
  }
  if (period.mode == PeriodMode.month) {
    return (period.ym ?? '').compareTo(now.substring(0, 7)) > 0 &&
        period.ym != null;
  }
  return false;
}
